typedef unsigned int MemSize;

enum MemoryBlockTypes {
    mbtFree = 0,
    mbtUsed = 1
};

struct MemFlagDWord {
    unsigned int pad : 24;
    unsigned int flags : 8;
};

struct MemBlockInfo {
    MemBlockInfo *prev;
    MemBlockInfo *next;
    MemBlockInfo *prevoftype;
    MemBlockInfo *nextoftype;
    MemSize size;
    MemFlagDWord flags;
};

class Heap {
    MemBlockInfo *fullhead;
    char padding[60];
    bool statsuptodate;
    char alignment[3];
    MemSize numblocks;
    MemSize numfree;
    MemSize numused;
    MemSize memblocks;
    MemSize memfree;
    MemSize memused;
    MemSize ovrblocks;
    MemSize ovrfree;
    MemSize ovrused;
    MemSize largestfree;

public:
    MemSize HeaderSize() const;
    MemSize FooterSize() const;
    void CheckHeapStats();
};

__asm__(".equ HeaderSize__C4Heap, 0x002AB370");
__asm__(".equ FooterSize__C4Heap, 0x002AB388");

void Heap::CheckHeapStats( void )
{
	if ( !statsuptodate )
	{
		statsuptodate=true;
		numblocks=0;
		numfree=0;
		numused=0;
		memblocks=0;
		memfree=0;
		memused=0;
		ovrblocks=0;
		ovrfree=0;
		ovrused=0;
		largestfree=0;
		MemBlockInfo *block=fullhead;
		while ( block )
		{
			numblocks++;
			memblocks+=block->size-FooterSize();
			ovrblocks+=HeaderSize()+FooterSize();
			if ( block->flags.flags & mbtUsed )
			{
				numused++;
				memused+=block->size-FooterSize();
				ovrused+=HeaderSize()+FooterSize();
			}
			else
			{
				numfree++;
				memfree+=block->size-FooterSize();
				ovrfree+=HeaderSize()+FooterSize();
				if ( block->size-FooterSize() > largestfree )
				{
					largestfree=block->size-FooterSize();
				}
			}
			block=block->next;
		}
	}
}
